# Controle Prioridade 1 Interface administrativa acessível apenas por rede interna ou VPN 🔴 Crítica 2 Somente <code>matomo.php</code>, <code>matomo.js</code> e <code>piwik.php</code> expostos publicamente 🔴 Crítica 3 WAF com OWASP CRS sobre o endpoint de coleta 🔴 Crítica 4 <code>force_ssl = 1</code> e HSTS habilitado 🔴 Crítica 5 MFA obrigatório para todos os usuários administrativos 🔴 Crítica 6 Usuário do banco com privilégio mínimo (sem <code>SUPER</code>, sem <code>FILE</code>) 🟠 Alta 7 <code>open_basedir</code> e <code>disable_functions</code> no PHP 🟠 Alta 8 Diretório <code>tmp/</code> fora da raiz web ou com execução negada 🟠 Alta 9 Plugins apenas do marketplace oficial, com revisão prévia 🟠 Alta 10 Segmentação de rede — a instância não acessa outras redes internas 🟠 Alta 11 Monitoramento de integridade de arquivos 🟡 Média 12 Rate limiting no endpoint de coleta 🟡 Média 13 Rotação e expiração de tokens de API 🟡 Média <pre><code># nginx.conf — exposição mínima do Matomo
server {
    listen 443 ssl http2;
    server_name analytics.ms.gov.br;

    ssl_protocols TLSv1.2 TLSv1.3;
    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "SAMEORIGIN" always;

    root /var/www/matomo;
    index index.php;

    # Endpoints públicos de coleta — únicos acessíveis pela internet
    location = /matomo.php { include fastcgi.conf; fastcgi_pass matomo:9000; }
    location = /matomo.js  { expires 1h; add_header Cache-Control "public"; }
    location = /piwik.php  { include fastcgi.conf; fastcgi_pass matomo:9000; }
    location = /piwik.js   { expires 1h; }

    # Interface administrativa — apenas rede interna
    location / {
        allow 10.0.0.0/8;
        allow 172.16.0.0/12;
        deny  all;
        try_files $uri $uri/ /index.php$is_args$args;
    }

    # Bloqueios explícitos
    location ~ ^/(config|core|lang|misc|plugins|tmp|vendor)/ { deny all; }
    location ~ \.(ini|log|sql|md|twig)$ { deny all; }
    location ~ /\. { deny all; }
}
</code></pre>
